    60	extern "C" int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size) {
    61	    int socket_fds[2];
    62	    int res = socketpair(AF_UNIX, SOCK_STREAM, 0, socket_fds);
    63	    assert(res >= 0);
    64	    ssize_t send_res = send(socket_fds[1], data, size, 0);
    65	    assert(send_res == size);
    66	    res = shutdown(socket_fds[1], SHUT_WR);
    67	    assert(res == 0);
    68	
    69	    int fd = open("/tmp/libssh_fuzzer_private_key", O_WRONLY | O_CREAT, S_IRWXU);
    70	    assert(fd >= 0);
    71	    ssize_t write_res = write(fd, kRSAPrivateKeyPEM, strlen(kRSAPrivateKeyPEM));
    72	    assert(write_res == strlen(kRSAPrivateKeyPEM));
    73	    close(fd);
    74	
    75	    ssh_bind sshbind = ssh_bind_new();
    76	    ssh_session session = ssh_new();
    77	
    78	    ssh_bind_options_set(sshbind, SSH_BIND_OPTIONS_RSAKEY, "/tmp/libssh_fuzzer_private_key");
    79	
    80	    res = ssh_bind_accept_fd(sshbind, session, socket_fds[0]);
    81	    assert(res == SSH_OK);
    82	
    83	    if (ssh_handle_key_exchange(session) == SSH_OK) {
    84	        while (true) {
    85	            ssh_message message = ssh_message_get(session);
    86	            if (!message) {
    87	                break;
    88	            }
    89	            ssh_message_free(message);
    90	        }
    91	    }
    92	
    93	    close(socket_fds[0]);
    94	    close(socket_fds[1]);
    95	
    96	    ssh_disconnect(session);
    97	    ssh_free(session);
    98	    ssh_bind_free(sshbind);
    99	
   100	    return 0;
   101	}
